/**
 * prepare-dataset.ts — build `ai/tinker/data/train.jsonl` (spec §28).
 *
 * Two honest sources, merged into one chat-format file:
 *
 * 1. `data/seed-curiosity.jsonl` — AUTHORED examples in TerraLens voice.
 *    Written by the project, not collected from anyone.
 * 2. `data/observations-export.json` — the user's OWN export (Settings →
 *    Export), optional. Training targets for these rows are generated by the
 *    DETERMINISTIC RULES ENGINE that ships in the app (`generateCuriosityAction`),
 *    so the tuned model distils real, reproducible behaviour — nothing here
 *    invents an assistant answer.
 *
 * Rows whose text trips the shipped BLOCKED safety rules are refused with a
 * loud warning, so a bad line can never quietly become training data.
 *
 * Run: `pnpm tinker:prepare`
 */
import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import { generateCuriosityAction } from "@/lib/curiosity/engine";
import {
  CuriosityActionCategorySchema,
  CuriosityActionSchema,
  EnvironmentSchema,
  ExpoModeSchema,
  ObservationCategorySchema,
  SafetyLevelSchema,
} from "@/lib/domain/types";
import type { MissionType, ObservationCategory } from "@/lib/domain/types";
import { scanTextForSafety } from "@/lib/safety/rules";
import { SYSTEM_PROMPT, buildUserMessage } from "./prompts";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA_DIR = path.join(ROOT, "data");
const SEED_FILE = path.join(DATA_DIR, "seed-curiosity.jsonl");
const EXPORT_FILE = path.join(DATA_DIR, "observations-export.json");
const OUT_FILE = path.join(DATA_DIR, "train.jsonl");

const SeedExampleSchema = z.object({
  category: ObservationCategorySchema,
  note: z.string().min(1).max(4000),
  mode: ExpoModeSchema,
  environment: EnvironmentSchema,
  actionCategory: CuriosityActionCategorySchema,
  shortInsight: z.string().min(1).max(400),
  physicalAction: z.string().min(1).max(600),
  nextMission: z.string().max(500).nullable().default(null),
  estimatedMinutes: z.number().int().min(1).max(60),
  safetyLevel: SafetyLevelSchema,
  requiresScreen: z.boolean().default(false),
});
type SeedExample = z.infer<typeof SeedExampleSchema>;

interface ChatRow {
  messages: Array<{ role: "system" | "user" | "assistant"; content: string }>;
}

function chatRow(user: string, actionJson: string): ChatRow {
  return {
    messages: [
      { role: "system", content: SYSTEM_PROMPT },
      { role: "user", content: user },
      { role: "assistant", content: actionJson },
    ],
  };
}

/**
 * Authored seed → chat rows. The assistant turn is exactly the CuriosityAction
 * shape the served adapter must learn to emit (same schema the app validates).
 */
function seedToRow(example: SeedExample): ChatRow {
  const action = CuriosityActionSchema.parse({
    shortInsight: example.shortInsight,
    physicalAction: example.physicalAction,
    nextMission: example.nextMission,
    estimatedMinutes: example.estimatedMinutes,
    requiresScreen: example.requiresScreen,
    safetyLevel: example.safetyLevel,
    category: example.actionCategory,
    generatedBy: "curiosity-adapter",
  });
  return chatRow(
    buildUserMessage({
      category: example.category,
      note: example.note,
      mode: example.mode,
      environment: example.environment,
    }),
    JSON.stringify(action)
  );
}

/** Minimal FNV-1a — stable ids for exported observations that lack one. */
function stableId(input: string): string {
  let h = 2166136261;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return `export-${(h >>> 0).toString(16)}`;
}

interface ExportObservation {
  id?: string;
  expeditionId?: string;
  category?: string;
  note?: string;
  capturedAt?: string;
}

interface ExportExpedition {
  id?: string;
  mode?: string;
  environment?: string;
}

interface ExportFile {
  observations?: ExportObservation[];
  expeditions?: ExportExpedition[];
}

/** Export → chat rows, targets produced by the REAL rules engine. */
function exportToRows(parsed: ExportFile): { rows: ChatRow[]; skipped: string[] } {
  const rows: ChatRow[] = [];
  const skipped: string[] = [];
  const expeditions = new Map<string, ExportExpedition>();
  for (const e of parsed.expeditions ?? []) {
    if (e.id) expeditions.set(e.id, e);
  }

  const observations = (parsed.observations ?? []).filter(
    (o): o is ExportObservation & { note: string } =>
      typeof o.note === "string" && o.note.trim().length > 0
  );
  // Earlier observations of the same expedition inform the engine's variety rules.
  const byExpedition = new Map<string, ExportObservation[]>();
  for (const o of observations) {
    const key = o.expeditionId ?? "_none";
    byExpedition.set(key, [...(byExpedition.get(key) ?? []), o]);
  }
  for (const list of byExpedition.values()) {
    list.sort(
      (a, b) =>
        (a.capturedAt ?? "").localeCompare(b.capturedAt ?? "") ||
        (a.id ?? "").localeCompare(b.id ?? "")
    );
  }

  const seenCategories = new Map<string, ObservationCategory[]>();
  for (const o of observations) {
    const category = ObservationCategorySchema.safeParse(o.category ?? "unknown");
    if (!category.success) {
      skipped.push(`observation ${o.id ?? "?"}: unknown category "${o.category}"`);
      continue;
    }
    const expedition = expeditions.get(o.expeditionId ?? "");
    const mode = ExpoModeSchema.safeParse(expedition?.mode ?? "nature");
    const environment = EnvironmentSchema.safeParse(expedition?.environment ?? "unknown");
    const expeditionKey = o.expeditionId ?? "_none";
    const recent = seenCategories.get(expeditionKey) ?? [];

    const action = generateCuriosityAction({
      observation: {
        id: o.id ?? stableId(`${category.data}\n${o.note}`),
        category: category.data,
        note: o.note,
      },
      expedition: {
        mode: mode.success ? mode.data : "nature",
        environment: environment.success ? environment.data : "unknown",
        title: "",
      },
      recentCategories: recent.slice(-5),
      completedMissionTypes: [] as MissionType[],
      accessibility: {
        reducedMotion: false,
        highContrast: false,
        largeText: false,
        captions: true,
        largeTouchTargets: false,
      },
    });

    if (action.safetyLevel === "blocked") {
      skipped.push(`observation ${o.id ?? "?"}: rules engine produced a blocked action`);
      continue;
    }

    rows.push(
      chatRow(
        buildUserMessage({
          category: category.data,
          note: o.note,
          mode: mode.success ? mode.data : "nature",
          environment: environment.success ? environment.data : "unknown",
        }),
        JSON.stringify(action)
      )
    );
    seenCategories.set(expeditionKey, [...recent, category.data]);
  }
  return { rows, skipped };
}

async function readSeed(): Promise<{ rows: ChatRow[]; refused: number }> {
  let text: string;
  try {
    text = await fs.readFile(SEED_FILE, "utf8");
  } catch {
    console.error(`No seed file at ${path.relative(process.cwd(), SEED_FILE)} — nothing to prepare.`);
    console.error("The authored seed ships with the repository; restore it and re-run.");
    process.exit(1);
  }

  const rows: ChatRow[] = [];
  let refused = 0;
  const lines = text.split("\n").filter((line) => line.trim().length > 0);
  lines.forEach((line, index) => {
    let json: unknown;
    try {
      json = JSON.parse(line);
    } catch {
      console.error(`Seed line ${index + 1} is not valid JSON — fix it and re-run. Nothing was written.`);
      process.exit(1);
    }
    const parsed = SeedExampleSchema.safeParse(json);
    if (!parsed.success) {
      const issue = parsed.error.issues[0];
      console.error(
        `Seed line ${index + 1} failed validation (${issue?.path.join(".")}: ${issue?.message}). Nothing was written.`
      );
      process.exit(1);
    }
    const scan = scanTextForSafety(
      `${parsed.data.shortInsight}\n${parsed.data.physicalAction}`
    );
    if (scan.level === "blocked") {
      console.warn(
        `Seed line ${index + 1} REFUSED — it trips the shipped safety rules (${scan.matchedRules.join(", ")}).`
      );
      refused += 1;
      return;
    }
    rows.push(seedToRow(parsed.data));
  });
  return { rows, refused };
}

async function readExport(): Promise<{ rows: ChatRow[]; skipped: string[]; present: boolean }> {
  let text: string;
  try {
    text = await fs.readFile(EXPORT_FILE, "utf8");
  } catch {
    return { rows: [], skipped: [], present: false };
  }
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    console.error(`${path.relative(process.cwd(), EXPORT_FILE)} is not valid JSON — fix it and re-run.`);
    process.exit(1);
  }
  const parsed = z
    .object({ observations: z.array(z.record(z.string(), z.unknown())).optional(), expeditions: z.array(z.record(z.string(), z.unknown())).optional() })
    .passthrough()
    .safeParse(json);
  if (!parsed.success) {
    console.error(
      `${path.relative(process.cwd(), EXPORT_FILE)} does not look like a TerraLens export (expected observations/expeditions arrays).`
    );
    process.exit(1);
  }
  // The settings export dump; cast through the narrow interfaces we read.
  const { rows, skipped } = exportToRows(json as ExportFile);
  return { rows, skipped, present: true };
}

async function main() {
  console.log("Tinker dataset preparation\n");

  const seed = await readSeed();
  console.log(`Seed (authored):     ${seed.rows.length} rows from data/seed-curiosity.jsonl`);
  if (seed.refused > 0) console.log(`                     ${seed.refused} refused by safety rules`);

  const exported = await readExport();
  if (exported.present) {
    console.log(
      `Export (your data):  ${exported.rows.length} rows from data/observations-export.json` +
        (exported.skipped.length > 0 ? ` (${exported.skipped.length} skipped)` : "")
    );
    console.log("                     Targets are the rules engine's own output — reproducible, never invented.");
    for (const reason of exported.skipped) console.log(`                     skip: ${reason}`);
  } else {
    console.log("Export (your data):  not present — training on the authored seed only.");
    console.log("                     Optional: drop a TerraLens settings export at data/observations-export.json");
    console.log("                     and re-run to add your own observations (labelled by the rules engine).");
  }

  const all = [...seed.rows, ...exported.rows];
  if (all.length === 0) {
    console.error("\nNo usable rows — nothing was written.");
    process.exit(1);
  }

  const body = all.map((row) => JSON.stringify(row)).join("\n") + "\n";
  await fs.writeFile(OUT_FILE, body, "utf8");

  console.log(`\nTotal:               ${all.length} rows → ${path.relative(process.cwd(), OUT_FILE)}\n`);
  console.log("Next steps:");
  console.log("  1. Fine-tune on Tinker with YOUR account — see ai/tinker/README.md and");
  console.log("     ai/tinker/config.example.json for the shape of a run.");
  console.log("  2. Serve the tuned checkpoint behind an OpenAI-compatible endpoint.");
  console.log("  3. TINKER_EVAL_BASE_URL=... TINKER_EVAL_MODEL=... pnpm tinker:evaluate");
}

void main();
